head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gNewWidthSize = 0;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// grid resize 시작부
frame.SetEvent("onwinstat", OnWinStat);
scwin.gOldWidthSize = frame.width;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name sleep
 * @description sleep 처리
 * @param {*} numberMillis numberMillis
 * @returns {void}
 * @hidden N
 */
scwin.sleep = function(numberMillis) {
    let now = new Date();
    const exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};

/**
 * @method
 * @name OnSized
 * @description On Sized 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};

/**
 * @method
 * @name OnSizedMax
 * @description On Sized Max 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};

/**
 * @method
 * @name OnWinStat
 * @description On Win Stat 처리
 * @param {String} winID winID
 * @param {*} statmsg statmsg
 * @returns {void}
 * @hidden N
 */
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg === "activate" && winID.substring(0, 6) === "Child_") {
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg === "maximize") {
        scwin.maxval = 1;
    } else if (statmsg === "size") {
        if (scwin.maxval === 0) {
            const strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval === 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};

/**
 * @method
 * @name GauceObjResize
 * @description 그리드메인
 * @param {*} a a
 * @param {*} b b
 * @returns {void}
 * @hidden N
 */
scwin.GauceObjResize = function(a, b) {
    // 그리드메인
    const gw = (a - parseInt(grd_List.getStyle("width")) - 30);
    grd_List.ReDraw = "false";
    grd_List.setGridWidth(parseInt(grd_List.getStyle("width")) + gw);
    grd_List.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;

    // 탭패널
    const pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__" + "panel_Top");
    pnl_main_grp.style.setGridWidth(parseInt(pnl_main_grp.style.width.replace("px", "")) + gw); // 상단패널
    panel_Top.style.width = parseInt(panel_Top.style.width.replace("px", "")) + gw;
    // 조회버튼
    btn_Search.style.left = parseInt(btn_Search.style.left.replace("px", "")) + gw;
    // 저장버튼
    btn_Close.style.left = parseInt(btn_Close.style.left.replace("px", "")) + gw;
    btn_Excel.style.left = parseInt(btn_Excel.style.left.replace("px", "")) + gw;
};

// grid resize 종료부

scwin.fr_SecuGrpId = SECUGRP_ID_EW;

/**
 * @method
 * @name refreshForm
 * @description refresh Form 처리
 * @param {*} interval interval
 * @returns {void}
 * @hidden N
 */
scwin.refreshForm = function(interval) {
    setInterval("fn_list_sync();", interval);
};

/**
 * @method
 * @name getParIsuCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
};

/**
 * @method
 * @name getDate
 * @description 직전영업일 가져옴
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_getDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_getDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&SDATE=" + edt_SDate.getValue();
    url += "&EDATE=" + edt_EDate.getValue();
    url += "&ISU_CD=" + txb_ISU_CD.getValue();

    // alert(getObjectValue(edt_SDate)+"//"+getObjectValue(edt_EDate)+"//"+getObjectValue(txb_ISU_CD));
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ELWEaryEnd.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    const res = window.confirm("[ " + dts_List.getCellData(dts_List.getRowPosition(), 'ISU_KOR_ABBRV') + " ] 확인 저장 하겠습니까?");
    // alert(js_id+"//"+dts_List.NameString(dts_List.RowPosition,'ISU_CD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_DD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_TM'));
    if (res) {
        url += "&USR_ID=" + js_id;
        url += "&ISU_CD=" + dts_List.getCellData(dts_List.getRowPosition(), 'ISU_CD');
        url += "&OCCR_DD=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_DD');
        url += "&OCCR_TM=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_TM');
        const sbmOptions = {
            id : "sbm_dts_parameter",
            action : "/ELWEaryEnd.do",
            ref : "",
            target : "dts_parameter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
    await scwin.listSync();
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    await scwin.listSync();
};

/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISU_NM_onclick = async function() {
    fn_GetPar = scwin.getParIsuCd;
    fn_SetPar = scwin.setParIsuCd;
    //    fn_PopFindIsu(fr_SecuGrpId);
    const options = {
        id: "ULDSTF92017_elwko",
        title: "종목선택",
        type: "browserPopup",
        width: "410px",
        height: "580px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../listingcommon/ULDSTF92017_elwko.gfm", options);
};

/**
 * @method
 * @name txb_ISU_CD_onblur
 * @description txb_ISU_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function() {
    if (txb_ISU_CD.getValue() === "") {
        txb_ISU_NM.setValue("");
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
};

/**
 * @method
 * @name img_SDate_onclick
 * @description img_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};

/**
 * @method
 * @name img_EDate_onclick
 * @description img_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    self.close();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀 로그
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    // 엑셀 로그
    $c.stf.doLogSave("ULDSTF41209.xml", SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List, {fileName: "ELW 조기종료발생현황", type: "8"});
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    $c.cm.PanelToGroupBox(panel_Top);
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    //    edt_SDate.text = cGetMinusDate2(vCurDate, 1);     // 일주일전 날짜
    await scwin.getDate();
    edt_SDate.setValue(dts_getDate.getCellData(1, "CALND_DD"));
    //    edt_SDate.text = vCurDate;     // 일주일전 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    await scwin.listSync();
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    scwin.refreshForm(60000);
};

/**
 * @method
 * @name grd_List_oncheckclick
 * @description grd_List oncheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_oncheckclick = async function(col, colid, bCheck) {
    if (bCheck !== 0) {
        await scwin.save();
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    await $c.win.alert(trs_Save);
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    await scwin.listSync();
    dts_List.reset();
};

/**
 * @method
 * @name dts_List_OnColumnChanged
 * @description List On Column Changed 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnColumnChanged = async function(row, colid) {
    if ((dts_List.getCellData(row, 'CHRG_CONFRM_YN') === 'T') &&
        (dts_List.OrgNameString(row, colid) !== dts_List.getCellData(row, colid)) &&
        (colid < 9)) {
        await $c.win.alert('변경불가');
        dts_List.undoRow(row);
    }

};

/**
 * @method
 * @name grd_List_CanColumnPosChange
 * @description grd List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
